        'district_varify_by'=>['VERIFY','DISTRICT','DISTRICT_VERIFIED'],
        'district_approve_by'=>['APPROVE','DISTRICT','DISTRICT_APPROVED'],
        'national_varify_by'=>['VERIFY','NATIONAL','NATIONAL_VERIFIED'],
        'national_approve_by'=>['APPROVE','NATIONAL','NATIONAL_APPROVED'],
