    private function insertWorkflow(string $table,string $requestId,array $workflow):int{$previous='CREATED';$count=0;foreach(self::WORKFLOW as $field=>[$action,$stage,$next]){$actor=$workflow[$field]??null;$user=$actor['target_user']['id']??null;if(!$user)continue;$this->target->prepare("INSERT INTO {$table}(record_origin,request_id,action,stage,user_id,comments,previous_status,new_status,action_at,timestamp_provenance,legacy_source_payload_json) VALUES('LEGACY_IMPORT',?,?,?,?,NULL,?,?,NULL,'UNAVAILABLE_FROM_LEGACY_SOURCE',?)")->execute([$requestId,$action,$stage,$user,$previous,$next,$this->json($actor)]);$previous=$next;$count++;}return $count;}
    private function decode(array $r):array{foreach(['historical_exception_types_json','current_conflict_types_json','blocker_types_json','source_references_json','workflow_json','location_provenance_json','source_provenance_json'] as $f)$r[$f]=json_decode((string)$r[$f],true)?:[];return $r;}
    private function officeCovers(array $office,string $officerId,?string $ascId,string $date):bool{if($ascId===null)return false;foreach($office[$officerId.'|'.$ascId]??[] as $period)if($period['effective_from']<=$date&&($period['effective_to']===null||$period['effective_to']>=$date))return true;return false;}
    private function workflowCount(array $r):int{$n=0;foreach(self::WORKFLOW as $field=>$_)if(!empty($r['workflow_json'][$field]['target_user']['id']))$n++;return $n;}
    private function targetWorkflowState(string $state):string{return match($state){'DRAFT'=>'CREATED','REJECTED_OR_RESET'=>'REJECTED',default=>in_array($state,['CREATED','SUBMITTED','ASC_VERIFIED','ASC_APPROVED','DISTRICT_VERIFIED','DISTRICT_APPROVED','NATIONAL_VERIFIED','NATIONAL_APPROVED','RETURNED','REJECTED'],true)?$state:'CREATED'};}
    private function profileExample(array $records):array{$out=[];foreach($records as $r)if($r['officer_dad_number']==='70045-0003443'&&in_array($r['effective_from'],['2025-01-01','2026-01-01'],true)&&in_array($r['appointment_type'],['PERMANENT','ACTING'],true))$out[]=['business_key'=>$r['reconciled_business_key'],'officer_dad_number'=>$r['officer_dad_number'],'officer_name'=>$r['officer_name'],'arpa_division'=>$r['resolved_arpa_name'],'appointment_type'=>$r['appointment_type'],'effective_from'=>$r['effective_from'],'source_current_classification'=>$r['current_classification'],'operational_projection'=>$r['operational_projection'],'legacy_history_only'=>$r['legacy_history_only'],'activation_block_reason'=>$r['activation_block_reason'],'exceptions'=>$r['historical_exception_types_json'],'source_references'=>$r['source_references_json']];return $out;}
    private function writeReport(array $summary,array $records,array $issues):string{$dir=BASE_PATH.'/storage/reports';if(!is_dir($dir))mkdir($dir,0770,true);$path=$dir.'/final-legacy-arpa-appointment-migration-dry-run-'.date('Ymd-His').'.json';$compact=array_map(fn(array $r):array=>['business_key'=>$r['reconciled_business_key'],'officer'=>$r['officer_dad_number'],'category'=>$r['assignment_category'],'type'=>$r['appointment_type']??$r['subject_kind'],'effective_from'=>$r['effective_from'],'effective_to'=>$r['effective_to'],'baseline_date'=>$r['baseline_date'],'baseline_classification'=>$r['baseline_classification'],'carried_into_baseline'=>$r['carried_into_baseline'],'migration_classification'=>$r['migration_classification'],'evidence_class'=>$r['special_evidence_class']??$r['location_confidence'],'resolved_asc_id'=>$r['resolved_asc_id'],'workflow_state'=>$r['workflow_state'],'operational_projection'=>$r['operational_projection'],'legacy_history_only'=>$r['legacy_history_only'],'activation_note'=>$r['activation_block_reason'],'manual_review_reasons'=>$r['manual_review_reasons'],'exceptions'=>$r['historical_exception_types_json'],'source_references'=>$r['source_references_json']],$records);file_put_contents($path,$this->json(['generated_at'=>date(DATE_ATOM),'summary'=>$summary,'issues'=>$issues,'records'=>$compact]),LOCK_EX);return $path;}
    private function subject(string $key):array{$s=$this->target->prepare("SELECT id,name_en FROM subject_master WHERE system_key=? AND active=1 AND approval_status='APPROVED'");$s->execute([$key]);$r=$s->fetch();if(!$r)throw new RuntimeException("Missing approved central subject {$key}.");return $r;}
    private function reason(?string $legacyId):?string{if(!$legacyId||!isset(self::REASONS[$legacyId]))return null;$s=$this->target->prepare("SELECT id FROM arpa_appointment_end_reason WHERE system_key=? AND active=1");$s->execute([self::REASONS[$legacyId]]);return $s->fetchColumn()?:null;}
    private function locations(array $ids):array{$ids=array_values(array_unique(array_filter($ids)));if(!$ids)return [];$s=$this->target->prepare('SELECT id,dad_number,name_en FROM location WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).')');$s->execute($ids);$out=[];foreach($s->fetchAll() as $r)$out[$r['id']]=$r;return $out;}
    private function uuid():string{return (string)$this->target->query('SELECT UUID()')->fetchColumn();}private function json(mixed $v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);}
